  (function buildProtagonist(){
    const EMBLEM_SOURCES=[
      "data:image/webp;base64,",
      "https://d8j0ntlcm91z4.cloudfront.net/user_3CB7QbfiArx9VIufTgzDQat3bei/hf_20260707_064703_64d42d90-cb34-4a6d-a133-ffa9fabc2b31.png"
    ];
    const done=reduceMotion?null:trackItem();
    let settled=false;
    function finish(){
      if(!settled){ settled=true; if(done) done(); if(stillRender) stillRender(); }
    }
    function mountTexture(tex){
      tex.minFilter=THREE.LinearFilter;
      const iw=(tex.image&&tex.image.width)||660, ih=(tex.image&&tex.image.height)||1024;
      const Hn=3.05, Wn=Hn*iw/ih;
      const plaque=new THREE.Mesh(
        new THREE.PlaneGeometry(Wn,Hn),
        new THREE.MeshBasicMaterial({map:tex,transparent:true,side:THREE.DoubleSide,depthWrite:false})
      );
      capsule.add(plaque);
      finish();
    }
    function proceduralCapsule(){
      const R=.85,HALF=1.15,SEGc=isMobile?24:40;
      const matRed=new THREE.MeshPhysicalMaterial({color:0x9c0f17,roughness:.22,metalness:.05,clearcoat:1,clearcoatRoughness:.18});
      const matIvory=new THREE.MeshPhysicalMaterial({color:0xf3ede1,roughness:.5,metalness:.02,clearcoat:.5,clearcoatRoughness:.35});
      const topCap=new THREE.Mesh(new THREE.SphereGeometry(R,SEGc,Math.round(SEGc*.6),0,Math.PI*2,0,Math.PI/2),matRed);
      topCap.position.y=HALF/2;
      const topBody=new THREE.Mesh(new THREE.CylinderGeometry(R,R,HALF/2,SEGc,1,true),matRed);
      topBody.position.y=HALF/4;
      const botBody=new THREE.Mesh(new THREE.CylinderGeometry(R,R,HALF/2,SEGc,1,true),matIvory);
      botBody.position.y=-HALF/4;
      const botCap=new THREE.Mesh(new THREE.SphereGeometry(R,SEGc,Math.round(SEGc*.6),0,Math.PI*2,Math.PI/2,Math.PI/2),matIvory);
      botCap.position.y=-HALF/2;
      const seam=new THREE.Mesh(new THREE.TorusGeometry(R+.005,.012,8,SEGc*2),new THREE.MeshPhysicalMaterial({color:0xd9cfbd,roughness:.4,metalness:.2}));
      seam.rotation.x=Math.PI/2;
      capsule.add(topCap,topBody,botBody,botCap,seam);
      capsule.rotation.z=Math.PI/2.4;
      finish();
    }
    function tryLoad(i){
      if(i>=EMBLEM_SOURCES.length){ proceduralCapsule(); return; }
      const u=EMBLEM_SOURCES[i];
      if(!u){ tryLoad(i+1); return; }
      const ld=new THREE.TextureLoader();
      ld.setCrossOrigin("anonymous");
      ld.load(u, mountTexture, undefined, function(){ tryLoad(i+1); });
    }
    tryLoad(0);
    setTimeout(finish, 9000);          /* never block the preloader */
  })();
